		sources: [
			"https://en.wikipedia.org/wiki/LGBTQ_rights_in_Latvia",
			"https://www.researchgate.net/publication/390502555_From_Social_Invisibility_to_Legal_Recognition_Same-Sex_Partnership_in_Latvia",
		],
